import manifest from './images.json';

export type ImageName = keyof typeof manifest;
type Entry = { widths: number[]; ratio: number; blur: string };
const table = manifest as Record<string, Entry>;

export const hasImage = (name: string): name is ImageName => name in table;

// Generated by scripts/optimize-images.mjs — re-run `npm run images` after changing ./assets.
export function imageSet(name: ImageName) {
  const { widths, ratio, blur } = table[name];
  const set = (ext: string) => widths.map((w) => `/img/${name}-${w}.${ext} ${w}w`).join(', ');
  return {
    avif: set('avif'),
    webp: set('webp'),
    jpg: set('jpg'),
    src: `/img/${name}-${widths[Math.min(1, widths.length - 1)]}.jpg`,
    small: `/img/${name}-${widths[0]}.webp`,
    ratio,
    blur,
  };
}
